"use strict";

export const format = {
  phoneNumber: {
    transform: a,
    reset: u
  },
  price: {
    transform: l,
    reset: f
  }
};
function u(r) {
  return String(r).replace(/\D/g, "");
}
function a(r) {
  const e = String(r),
    s = e.slice(0, 2) === "02" ? e.slice(0, 10) : e.slice(0, 11),
    d = (t, c) => {
      for (const n of c) {
        const o = i(t, n);
        if (o) return o;
      }
      return t;
    },
    i = (t, c) => {
      const n = t.match(c);
      if (n) return n.slice(1, 4).filter(o => o.length > 0).join("-");
    };
  return d(s, [/^(010)(\d{1,4})(\d{0,4})$/, /^(02)(\d{1,3})(\d{0,4})$/, /^(02)(\d{1,4})(\d{0,4})$/, /^(\d{3})(\d{1,3})(\d{0,4})$/, /^(\d{3})(\d{1,4})(\d{0,4})$/, /(\d*)/]);
}
function f(r) {
  const e = String(r);
  return String(e.replace(/,/g, ""));
}
function l(r) {
  return String(r).replace(/(\d)(?=(\d\d\d)+(?!\d))/g, "$1,");
}